200 &= \left( \pi^2 \times 200^2 \times \frac{1}{16}\right)^{1/4} \times \left( \frac{2}{\left( \left( \left( \frac{16 \times 200}{\pi^2}\right)^{1/4} \right) / 200 \right)}\right) &\text{Replace the expression for the diameter} \\
200 &= \frac{2}{\left( \left( \left( \frac{16 \times 200}{\pi^2}\right)^{1/4} \right) / 200 \right)} &\text{Simplify} \\
